import { languageSelector } from "~/renderer/reducers/settings";

const WWW_DOMAIN = "www.ledger.com";
const SUPPORT_DOMAIN = "support.ledger.com";
const SHOP_DOMAIN = "shop.ledger.com";

const wwwLocaleMap: Record<string, string> = {
  pt: "pt-br",
  zh: "zh-hans",
};

const supportLocaleMap: Record<string, string> = {
  fr: "fr-fr",
  en: "en-us",
  zh: "zh-cn",
};

const shopLocaleMap: Record<string, string> = {
  pt: "pt-br",
};

export function useLocalizedUrl(url: string): string {
  const locale = useSelector(languageSelector);

  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return url;
  }

  switch (parsed.hostname) {
    case WWW_DOMAIN: {
      const localeCode = wwwLocaleMap[locale] || locale;
      parsed.pathname = `/${localeCode}${parsed.pathname}`;
      return parsed.toString();
    }
    case SUPPORT_DOMAIN: {
      if (!parsed.pathname.startsWith("/hc/")) return url;
      const localeCode = supportLocaleMap[locale] || locale;
      parsed.pathname = parsed.pathname.replace("/hc/", `/hc/${localeCode}/`);
      return parsed.toString();
    }
    case SHOP_DOMAIN: {
      const localeCode = shopLocaleMap[locale] || locale;
      parsed.pathname = `/${localeCode}${parsed.pathname}`;
      return parsed.toString();
    }
    default:
      return url;
  }
}

export default useLocalizedUrl;
